sparql:
SELECT DISTINCT ?player ?club WHERE {
  { SELECT DISTINCT ?club WHERE { ?club a vio:FootballClub ; rdfs:label ?n .
                                  FILTER(LCASE(STR(?n)) = "câu lạc bộ bóng đá hoàng anh gia lai") } }
  ?player vio:playedFor ?club .
} ORDER BY ?player

SELECT DISTINCT ?player ?club WHERE {
  { SELECT DISTINCT ?club WHERE { ?club a vio:FootballClub ; rdfs:label|skos:altLabel ?n .
                                  FILTER(CONTAINS(LCASE(STR(?n)), "than quảng ninh")) } }
  ?player vio:playedFor ?club .
} ORDER BY ?player LIMIT 50

SELECT DISTINCT ?player ?team ?start ?end ?apps ?goals WHERE {
  { SELECT DISTINCT ?player WHERE { ?player a vio:FootballPlayer ; rdfs:label|skos:altLabel ?n .
                                    FILTER(CONTAINS(LCASE(STR(?n)), "công phượng")) } }
  ?player vio:careerStation ?st . ?st a vio:ClubStation ; vio:team ?team .
  OPTIONAL { ?st vio:startYear ?start } OPTIONAL { ?st vio:endYear ?end }
  OPTIONAL { ?st vio:appearances ?apps } OPTIONAL { ?st vio:goals ?goals }
} ORDER BY ?start LIMIT 50

SELECT DISTINCT ?club ?stadium ?province WHERE {
  { SELECT DISTINCT ?province WHERE { ?province a vio:Province ; rdfs:label ?pl .
                                      FILTER(LCASE(STR(?pl)) = "hà nội") } }
  ?stadium vio:province ?province . ?club a vio:FootballClub ; vio:ground ?stadium .
} LIMIT 50

SELECT ?province (COUNT(DISTINCT ?p) AS ?n) WHERE {
  ?p a vio:FootballPlayer ; vio:birthProvince ?province .
} GROUP BY ?province ORDER BY DESC(?n) LIMIT 10

SELECT DISTINCT ?university ?dbpedia WHERE {
  { SELECT DISTINCT ?university WHERE { ?university a vio:University ; rdfs:label|skos:altLabel ?l .
                                        FILTER(CONTAINS(LCASE(STR(?l)), "đại học cần thơ")) } }
  ?university owl:sameAs ?dbpedia . FILTER(STRSTARTS(STR(?dbpedia), "http://dbpedia.org/resource/"))
} LIMIT 10
